import { useEffect, useMemo, useState } from 'react';
import { CheckCircle2, CircleAlert, Clock, HelpCircle, Search, Star, StarOff } from 'lucide-react';
import {
  isStopStarred,
  recordTripCheck,
  starStop,
  unstarStop,
} from '../lib/favourites';
import { api } from '../lib/api';
import type { ReliabilityNode, TripCheckResponse } from '../types';
import {
  TRIP_CHECK_SNAPSHOT_PREFIX,
  pathWasReplayed,
} from '../lib/static-patch';
import ReplayNotice from './ReplayNotice';
import StopSearch from './StopSearch';
import SourceNote from './SourceNote';

/**
 * Rider-facing "Will I make it?" (P5.5).
 *
 * One question, one honest answer: arriving on route A at a transfer stop,
 * will I catch route B? The verdict comes from the collector's observed
 * lateness (same model as the reliability map) and is deliberately hedged —
 * 'tight' outcomes name the miss probability; unmeasured pairs say so
 * instead of guessing.
 */

const VERDICT_STYLE: Record<
  NonNullable<TripCheckResponse['verdict']>,
  { icon: typeof CheckCircle2; color: string; label: string }
> = {
  // Dark-theme palette (P7.8 pass-2 finding: the light-theme -600 variants
  // are near-invisible on #121212). Map to the design system tokens.
  likely: { icon: CheckCircle2, color: 'text-[color:var(--color-optimized)]', label: 'Likely' },
  tight: { icon: Clock, color: 'text-[color:var(--color-bottleneck)]', label: 'Tight' },
  unlikely: { icon: CircleAlert, color: 'text-[color:var(--color-danger)]', label: 'Unlikely' },
  unknown: { icon: HelpCircle, color: 'text-text-muted', label: 'Not enough data' },
};

export default function TripCheckPanel({
  /** Tier 2.3: deep-linked inputs (?tc=&arr=&dep=&slack=) from the entry
   *  URL. Only used on mount — the URL is the entry state, not live state. */
  initialParams,
}: {
  initialParams?: { stop: string; arrive: string; depart: string; slack?: number } | null;
} = {}) {
  const [nodes, setNodes] = useState<ReliabilityNode[] | null>(null);
  const [nodesError, setNodesError] = useState<string | null>(null);
  // A7: re-running a recent check from the rider home lands here with a
  // one-shot sessionStorage prefill (stop + route pair). A deep-link URL
  // (Tier 2.3) wins when both are present — the URL is the more deliberate
  // entry.
  const prefill = (() => {
    if (initialParams) {
      return { stopId: initialParams.stop, routeArrive: initialParams.arrive, routeDepart: initialParams.depart };
    }
    try {
      const raw = sessionStorage.getItem('miway-tripcheck-prefill');
      if (!raw) return null;
      sessionStorage.removeItem('miway-tripcheck-prefill');
      const v = JSON.parse(raw) as {
        stopId?: string;
        routeArrive?: string;
        routeDepart?: string;
      };
      return v && typeof v.stopId === 'string' ? v : null;
    } catch {
      return null;
    }
  })();
  const [stopId, setStopId] = useState(prefill?.stopId ?? '');
  const [routeArrive, setRouteArrive] = useState(prefill?.routeArrive ?? '');
  const [routeDepart, setRouteDepart] = useState(prefill?.routeDepart ?? '');
  const [slack, setSlack] = useState(initialParams?.slack ?? 0);
  const [result, setResult] = useState<TripCheckResponse | null>(null);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);
  // 3.2 foundations (A7): star/unstar this stop; the rider home lists it.
  const [starred, setStarred] = useState(false);

  // The reliability map is the source of transfer stops + their route pairs;
  // reusing it means the rider view can never offer a pair the map doesn't.
  // useEffect, not useMemo: a fetch is a side effect, and React may discard a
  // render pass — dropping a useMemo-fired fetch leaves the skeleton forever
  // (observed live on the P7.8 skeptic pass).
  useEffect(() => {
    let cancelled = false;
    api
      .measuredReliability()
      .then((r) => {
        if (!cancelled) setNodes(r.nodes ?? []);
      })
      .catch((e) => {
        if (!cancelled) setNodesError(String(e));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const stop = useMemo(
    () => nodes?.find((n) => n.stop_id === stopId) ?? null,
    [nodes, stopId],
  );

  // Track the starred flag for the currently selected stop (and reset when
  // the pick changes). Best-effort read; the toggle writes through the lib.
  useEffect(() => {
    setStarred(stopId ? isStopStarred(stopId) : false);
  }, [stopId]);

  /** Direction name for a route at this stop, from the node's GTFS
      headsigns; empty when the feed didn't provide one. */
  function routeHeadsign(
    node: NonNullable<typeof stop>,
    route: string,
  ): string {
    return node.route_headsigns?.[route] ?? '';
  }

  async function check() {
    if (!stopId || !routeArrive || !routeDepart) return;
    setChecking(true);
    setResult(null);
    setCheckError(null);
    try {
      setResult(await api.tripCheck(stopId, routeArrive, routeDepart, slack));
      // Tier 2.3: a successful answer is shareable — encode the inputs into
      // the URL (hash-carried on the Pages demo, query on real paths) so
      // "paste this link" replays the exact check. replaceState, not push:
      // the check itself isn't a navigation.
      try {
        const sp = new URLSearchParams(window.location.search);
        sp.set('tc', stopId);
        sp.set('arr', routeArrive);
        sp.set('dep', routeDepart);
        if (slack > 0) sp.set('slack', String(slack));
        else sp.delete('slack');
        const base = `${window.location.pathname}${window.location.search}`;
        const next = `${base}${base.includes('?') ? '&' : '?'}${
          ['tc', 'arr', 'dep', 'slack']
            .map((k) => [k, sp.get(k)])
            .filter(([, v]) => v != null)
            .map(([k, v]) => `${k}=${encodeURIComponent(v as string)}`)
            .join('&')
        }`;
        window.history.replaceState(null, '', next);
      } catch {
        // URL write is best-effort; the check result itself is unaffected.
      }
      // Record the connection for the rider home's "recent checks" list —
      // after a successful answer, so a failed check doesn't pollute it.
      recordTripCheck({
        stopId,
        stopName: stop?.stop_name ?? stopId,
        routeArrive,
        routeDepart,
      });
      window.dispatchEvent(new Event('miway:favourites-changed'));
    } catch (e) {
      // Inline error, not a crash: a failed check (backend down, live tunnel
      // away, snapshot missing) must not take the whole app down — this
      // handler IS the demo-mode story for the check button.
      setCheckError(e instanceof Error ? e.message : String(e));
    } finally {
      setChecking(false);
    }
  }

  if (nodesError) {
    return (
      <div className="p-4 text-sm text-[color:var(--color-danger)]">
        Reliability data unavailable: {nodesError}
      </div>
    );
  }
  // A12 (2026-09-27): no page-level skeleton. The form renders immediately;
  // while the stop list loads the route dropdowns sit disabled with a hint —
  // a grey full-viewport block read as "broken", not "loading".

  return (
    <div className="space-y-3 p-4">
      <p className="text-sm text-text-secondary">
        Pick a transfer stop and a route pair. The answer comes from{' '}
        <strong>observed</strong> bus departures — not promises — so it carries
        uncertainty and sometimes says "not enough data".
      </p>

      <label className="block text-xs font-medium text-text-secondary">
        Transfer stop
        <div className="mt-1">
          <StopSearch
            stops={(nodes ?? []).map((n) => ({
              stop_id: n.stop_id,
              label: `${n.stop_name} (${n.routes.length} routes)`,
            }))}
            value={stopId}
            onChange={(v) => {
              setStopId(v);
              setRouteArrive('');
              setRouteDepart('');
              setResult(null);
            }}
          />
        </div>
      </label>
      {nodes === null && (
        <p className="animate-pulse text-[11px] text-text-muted" role="status">
          Loading transfer stops…
        </p>
      )}

      {stop && (
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => {
              if (isStopStarred(stop.stop_id)) {
                unstarStop(stop.stop_id);
                setStarred(false);
              } else {
                starStop({ stopId: stop.stop_id, stopName: stop.stop_name, routes: stop.routes });
                setStarred(true);
              }
              window.dispatchEvent(new Event('miway:favourites-changed'));
            }}
            className="col-span-2 inline-flex items-center justify-center gap-1.5 rounded border border-border px-2 py-1.5 text-xs font-medium text-text-secondary transition-colors hover:border-accent/50 hover:text-accent"
            title={starred ? 'Remove this stop from your saved stops on the home screen' : 'Save this stop to your home screen for quick access'}
          >
            {starred ? <StarOff size={14} /> : <Star size={14} />}
            {starred ? 'Saved to home — click to remove' : 'Save this stop to your home'}
          </button>
          <label className="block text-xs font-medium text-text-secondary">
            Arriving on
            <select
              className="mt-1 w-full rounded border border-border bg-card p-2 text-sm text-text-primary"
              value={routeArrive}
              onChange={(e) => setRouteArrive(e.target.value)}
            >
              <option value="">— route —</option>
              {stop.routes.map((r) => (
                <option key={r} value={r}>
                  {routeHeadsign(stop, r) ? `${r} — ${routeHeadsign(stop, r)}` : r}
                </option>
              ))}
            </select>
          </label>
          <label className="block text-xs font-medium text-text-secondary">
            Catching
            <select
              className="mt-1 w-full rounded border border-border bg-card p-2 text-sm text-text-primary"
              value={routeDepart}
              onChange={(e) => setRouteDepart(e.target.value)}
            >
              <option value="">— route —</option>
              {stop.routes.map((r) => (
                <option key={r} value={r}>
                  {routeHeadsign(stop, r) ? `${r} — ${routeHeadsign(stop, r)}` : r}
                </option>
              ))}
            </select>
          </label>
        </div>
      )}

      <label className="block text-xs font-medium text-text-secondary">
        Extra minutes you planned beyond the schedule ({slack})
        <input
          type="range" min={0} max={10} step={1} value={slack}
          onChange={(e) => setSlack(Number(e.target.value))}
          className="w-full"
        />
      </label>

      <button
        className="flex w-full items-center justify-center gap-2 rounded bg-sky-700 p-2 text-sm font-medium text-white disabled:opacity-40"
        disabled={!stopId || !routeArrive || !routeDepart || checking}
        onClick={check}
      >
        <Search size={14} /> {checking ? 'Checking…' : 'Check connection'}
      </button>

      {checkError && (
        <div role="alert" className="rounded border border-[color:var(--color-danger)]/40 bg-[color:var(--color-danger)]/10 p-3 text-sm text-[color:var(--color-danger)]">
          Check failed: {checkError}. The connection answer needs the live collector or a fresh snapshot — try again later.
        </div>
      )}

      {result && (
        <div className="rounded border border-border p-3">
          {pathWasReplayed(TRIP_CHECK_SNAPSHOT_PREFIX) && (
            <ReplayNotice
              whatYouAsked={`${stop?.stop_name ?? stopId} · ${routeArrive} → ${routeDepart}`}
              replayIs={`${result.stop_name ?? result.stop_id ?? 'City Centre'} · ${result.route_arrive} → ${result.route_depart}`}
            />
          )}
          {result.found ? (
            <>
              <div className={`flex items-center gap-2 font-semibold ${VERDICT_STYLE[result.verdict ?? 'unknown'].color}`}>
                {(() => {
                  const V = VERDICT_STYLE[result.verdict ?? 'unknown'].icon;
                  return <V size={18} />;
                })()}
                {VERDICT_STYLE[result.verdict ?? 'unknown'].label}
                {result.measured && result.p_miss != null && (
                  <span className="ml-auto text-xs font-normal text-text-muted">
                    miss risk {(result.p_miss * 100).toFixed(0)}%
                  </span>
                )}
              </div>
              {/* Direction disclosure (user pass-2 finding): a bare "38 → 43"
                  hides WHERE each bus is going, which is exactly what makes a
                  same-street opposite-direction pairing look like nonsense. */}
              {(result.headsign_arrive || result.headsign_depart) && (
                <p className="mt-1 text-xs text-text-secondary">
                  {result.headsign_arrive && <span>arriving on the {result.headsign_arrive}</span>}
                  {result.headsign_arrive && result.headsign_depart && <span>{' · '}</span>}
                  {result.headsign_depart && <span>catching the {result.headsign_depart}</span>}
                </p>
              )}
              {result.earlier_alternative && (
                <p className="mt-1 rounded border border-border bg-card px-2 py-1.5 text-xs text-text-secondary">
                  Same connection works earlier: get off {result.earlier_alternative.stops_earlier}{' '}
                  {result.earlier_alternative.stops_earlier === 1 ? 'stop' : 'stops'} sooner at{' '}
                  <strong className="text-text-primary">{result.earlier_alternative.stop_name}</strong>{' '}
                  (scheduled wait {result.earlier_alternative.scheduled_wait_min} min).
                </p>
              )}
              <p className="mt-2 text-sm text-text-primary">{result.message}</p>
              {result.measured && (
                <dl className="mt-2 grid grid-cols-3 gap-2 text-center text-xs text-text-secondary">
                  <div>
                    <dt className="font-medium text-text-primary">{result.scheduled_wait_min}</dt>
                    <dt>scheduled wait</dt>
                  </div>
                  <div>
                    <dt className="font-medium text-text-primary">{result.realized_median_wait_min}</dt>
                    <dt>typical wait</dt>
                  </div>
                  <div>
                    <dt className="font-medium text-text-primary">
                      {result.n_obs_arrive != null && result.n_obs_depart != null
                        ? (result.n_obs_arrive + result.n_obs_depart).toLocaleString()
                        : '—'}
                    </dt>
                    <dt>
                      {result.n_obs_arrive != null && result.n_obs_depart != null
                        ? `obs (${result.n_obs_arrive.toLocaleString()} arr + ${result.n_obs_depart.toLocaleString()} dep)`
                        : 'obs (counts unavailable)'}
                    </dt>
                  </div>
                </dl>
              )}
            </>
          ) : (
            <p className="text-sm text-text-secondary">{result.message}</p>
          )}
          <SourceNote
            source={`Measured from GTFS-RT observed departures; ${result.method ?? 'uncertainty is reported, never hidden'}.`}
          />
        </div>
      )}
    </div>
  );
}
